let fail = 0, n = 0;
for (const [name, list] of Object.entries(REF)) {
  const th = FLUID_THERMO[name];
  if (!th) { console.log(`FAIL  ${name}: no FLUID_THERMO entry`); fail++; continue; }
  for (const p of list) {
    if (p.T < th.Tmin - 1e-6 || p.T > th.Tmax + 1e-6) continue;
    const r = computeLiquidProps(name, p.T, p.P ?? NaN);
    const got = { rho: r.sg * 999, pv: r.pv_psia * 0.0689475729, mu: r.visc_cP };
    for (const k of ['rho', 'pv', 'mu']) {
      if (p[k] == null || (k === 'pv' && p[k] < 1e-3)) continue;
      n++;
      const err = 100 * (got[k] / p[k] - 1);
      if (!isFinite(err) || Math.abs(err) > TOL[name][k]) {
        fail++;
        console.log(`FAIL  ${name} @${p.T} °C ${k}: got ${got[k].toPrecision(5)} ref ${p[k]} (${err.toFixed(2)} %, tol ${TOL[name][k]} %) [${p.src}]`);
      }
    }
  }
}
// every liquid preset must have a property entry
const DB = new Function(html.slice(a, b) + '\nreturn FLUID_DB;')();
for (const g of ['liq_gen', 'liq_chem']) for (const f of DB[g]) if (!FLUID_THERMO[f.n]) { console.log(`FAIL  preset "${f.n}" has no FLUID_THERMO entry`); fail++; }
console.log(`${n} checks, ${fail} failures`);
process.exit(fail ? 1 : 0);
